import React from "react";

function Footer() {
  return (
    <footer
      style={{
        background: "#1e293b",
        color: "white",
        padding: "20px",
        marginTop: "40px",
        textAlign: "center",
      }}
    >
      <h3>Doctor Booking System</h3>

      <p>Book appointments with top doctors easily.</p>

      <p>Email: support@doctorbooking.com</p>

      <p>Phone: +91 9876543210</p>

      <p style={{ marginTop: "10px", fontSize: "14px" }}>
        © 2026 Doctor Booking App. All rights reserved.
      </p>
    </footer>
  );
}

export default Footer;
